//#region src/error.ts
var FSRSError = class FSRSError extends Error {
	constructor(message = "FSRS Error") {
		super(message);
		this.name = "FSRSError";
		Error.captureStackTrace?.(this, FSRSError);
	}
};
var FSRSValidationError = class FSRSValidationError extends FSRSError {
	constructor(message) {
		super(message);
		this.name = "FSRSValidationError";
		Error.captureStackTrace?.(this, FSRSValidationError);
	}
};
var FSRSOperationError = class FSRSOperationError extends FSRSError {
	constructor(message) {
		super(message);
		this.name = "FSRSOperationError";
		Error.captureStackTrace?.(this, FSRSOperationError);
	}
};

//#endregion
export { FSRSError, FSRSOperationError, FSRSValidationError };